BEGIN;
CREATE TABLE IF NOT EXISTS public.iara_pix_invoices (id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,product_id TEXT NOT NULL,client_id TEXT NOT NULL,gateway_id TEXT,transaction_id UUID REFERENCES public.gateway_transactions(id),amount_cents BIGINT NOT NULL CHECK(amount_cents>0),discount_cents BIGINT NOT NULL DEFAULT 0 CHECK(discount_cents>=0),final_amount_cents BIGINT NOT NULL CHECK(final_amount_cents>0),currency TEXT NOT NULL DEFAULT 'BRL' CHECK(currency='BRL'),pix_key TEXT NOT NULL,txid TEXT NOT NULL,emv_payload TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PENDING' CHECK(status IN('PENDING','PAID','EXPIRED','CANCELED')),expires_at TIMESTAMPTZ NOT NULL,paid_at TIMESTAMPTZ,provider_payment_id TEXT,created_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc',now()),updated_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc',now()),CONSTRAINT iara_pix_amount_integrity CHECK(final_amount_cents=amount_cents-discount_cents),CONSTRAINT iara_pix_txid_unique UNIQUE(user_id,txid),CONSTRAINT iara_pix_transaction_user_fk UNIQUE(user_id,transaction_id));
CREATE INDEX IF NOT EXISTS idx_iara_pix_invoices_user_status_created ON public.iara_pix_invoices(user_id,status,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_iara_pix_invoices_user_expires ON public.iara_pix_invoices(user_id,expires_at) WHERE status='PENDING';
CREATE TABLE IF NOT EXISTS public.iara_pix_webhook_events(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,event_id TEXT NOT NULL,pix_invoice_id UUID REFERENCES public.iara_pix_invoices(id) ON DELETE RESTRICT,provider_payment_id TEXT,payload JSONB NOT NULL DEFAULT '{}'::jsonb,signature_verified BOOLEAN NOT NULL DEFAULT FALSE,received_at TIMESTAMPTZ NOT NULL DEFAULT timezone('utc',now()),processed_at TIMESTAMPTZ,UNIQUE(user_id,event_id));
CREATE INDEX IF NOT EXISTS idx_iara_pix_webhook_events_invoice ON public.iara_pix_webhook_events(user_id,pix_invoice_id,received_at DESC);
ALTER TABLE public.iara_pix_invoices ENABLE ROW LEVEL SECURITY; ALTER TABLE public.iara_pix_webhook_events ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS iara_pix_invoices_select_own ON public.iara_pix_invoices; CREATE POLICY iara_pix_invoices_select_own ON public.iara_pix_invoices FOR SELECT TO authenticated USING(user_id=auth.uid());
DROP POLICY IF EXISTS iara_pix_webhook_events_select_own ON public.iara_pix_webhook_events; CREATE POLICY iara_pix_webhook_events_select_own ON public.iara_pix_webhook_events FOR SELECT TO authenticated USING(user_id=auth.uid());
REVOKE INSERT,UPDATE,DELETE ON public.iara_pix_invoices FROM anon,authenticated; REVOKE INSERT,UPDATE,DELETE ON public.iara_pix_webhook_events FROM anon,authenticated;
COMMIT;